// Ported from Akantu (EPFL/LSMS): test/test_model/test_solid_mechanics_model/
// test_embedded_interface/test_embedded_element_matrix.cc,
// test_embedded_interface_model.cc, test_embedded_interface_model_prestress.cc
// (setups), compared with the patched oracle variant `embedded` (D-060).

//! Replay of the golden fixtures `fixtures/model/embedded/*`, generated by
//! `oracle/probes/embedded/embedded_probe.cc` on the patched oracle variant
//! `embedded` (`oracle/patches/embedded`, D-060, docs/ORACLE_BUILD.md):
//! upstream's three embedded tests (TEST-125/126/127), an oblique bar,
//! pre-stress at rest in 2-D and 3-D, a `_triangle_6`
//! background, and adversarial and grazing bars.
//!
//! The inputs (bars, input file, displacement-field seed) are read back from
//! each manifest's parameters, so both sides run the same numbers. The port
//! runs in upstream-compatible mode: the collected set
//! (`remove_near_duplicates = false`, UD-599/UD-601), upstream's segment
//! order (UD-408) and, in 3-D, upstream's flat tetrahedron triangles
//! (UD-407).
//!
//! * The interface pieces must equal the oracle's as a **set** (background
//!   element and both end points, bitwise; orientation free).
//! * When the interface element order equals the oracle's, every quantity is
//!   compared in place (exact rule of `fixtures/model/embedded/tolerances.json`).
//! * When it differs (the LGPL search structure cannot reproduce the CGAL
//!   AABB tree's order, UD-408), the port's data are put in the oracle's
//!   order (interface elements matched by background element and end points,
//!   `K` by `(row, col)`), and compared with the case's rule in
//!   `tolerances.json` (exact if the assembled values are bitwise, else the
//!   PROPOSED rule `emb_order`); the test also asserts that the order
//!   indeed differs for those cases.
//!
//! Default-mode replays: where the default construction (interval tiling)
//! gives the same pieces as upstream (2-D cases without near-duplicates),
//! the default results are compared with the same fixtures.

mod common;

use std::collections::{BTreeMap, HashMap};

use akantu_core::enums::{AnalysisMethod, SpatialDirection};
use akantu_core::{ElementType, GhostType, Real};
use akantu_embedded::{EmbeddedInterfaceModel, EmbeddedInterfaceModelOptions};
use akantu_geometry::{SegmentIntersectorOptions, SegmentOrder};
use akantu_mesh::{Mesh, MeshAccessor};
use akantu_model::boundary_condition::FixedValue;
use akantu_model::constitutive_law::LawPhase;
use akantu_validation::fixture::Fixture;
use akantu_validation::harness::DiffTest;

/// Cases whose interface element order, or which of two exact duplicates
/// survives, differs from the oracle's (UD-408: upstream's `std::set` with
/// the invalid comparator `segmentPairsLess` depends on the CGAL AABB tree's
/// traversal order); they are compared with the PROPOSED rule `emb_order`
/// of `tolerances.json`. Every other 2-D case must match in place and
/// bitwise.
const ORDER_DIFFERS: &[&str] = &[
    "t127",
    "adversarial_2d",
    "prestress_2d_rest",
    "grazing_2d_1e-4",
    "grazing_2d_1e-10",
];

/// Upstream-compatible intersector options of the port (`order`: upstream's
/// segment set, or the exact deduplication when the LGPL search order does
/// not reproduce upstream's survivors, UD-408).
fn compat(model: &mut EmbeddedInterfaceModel, dim: usize, order: SegmentOrder) {
    model.intersector.remove_near_duplicates = false;
    model.intersector.options = if dim == 3 {
        SegmentIntersectorOptions {
            order,
            ..SegmentIntersectorOptions::upstream()
        }
    } else {
        SegmentIntersectorOptions {
            order,
            ..SegmentIntersectorOptions::default()
        }
    };
}

/// Deterministic field of embedded_probe.cc (64-bit LCG, amplitude 1e-3).
fn random_field(model: &mut EmbeddedInterfaceModel, seed: u64) {
    let mut s = seed;
    let mut u = model.smm.displacement_mut().unwrap();
    for x in u.as_mut_slice() {
        s = s
            .wrapping_mul(6_364_136_223_846_793_005)
            .wrapping_add(1_442_695_040_888_963_407);
        *x = 1e-3 * (((s >> 11) as Real) / ((1u64 << 53) as Real) * 2.0 - 1.0);
    }
}

/// `n × n` cells over the unit square, two `_triangle_6` per cell (corners
/// as `grid_triangles`, mid-edge nodes 3, 4, 5 between corners (0,1), (1,2),
/// (2,0)) on the `(2n + 1)²` lattice — embedded_probe.cc `grid_triangles6`.
fn grid_triangles6(n: usize) -> Mesh {
    let mut mesh = Mesh::new(2, "mesh").unwrap();
    let g = 2 * n + 1;
    let id = |i: usize, j: usize| i32::try_from(j * g + i).unwrap();
    let mut count = 0;
    {
        let mut acc = MeshAccessor::new(&mut mesh);
        for j in 0..g {
            for i in 0..g {
                acc.push_node(&[i as Real / (2 * n) as Real, j as Real / (2 * n) as Real])
                    .unwrap();
            }
        }
        let mut c = acc.connectivity_mut(ElementType::Triangle6, GhostType::NotGhost);
        for j in 0..n {
            for i in 0..n {
                let (a, b) = (2 * i, 2 * j);
                c.try_push_tuple(&[
                    id(a, b),
                    id(a + 2, b),
                    id(a + 2, b + 2),
                    id(a + 1, b),
                    id(a + 2, b + 1),
                    id(a + 1, b + 1),
                ])
                .unwrap();
                c.try_push_tuple(&[
                    id(a, b),
                    id(a + 2, b + 2),
                    id(a, b + 2),
                    id(a + 1, b + 1),
                    id(a + 1, b + 2),
                    id(a, b + 1),
                ])
                .unwrap();
                count += 2;
            }
        }
    }
    common::name_elements(&mut mesh, ElementType::Triangle6, count, "concrete");
    mesh
}

/// The `bars` parameter of a generated case: `[(x, y[, z])(…)…][…]`.
fn parse_bars(text: &str) -> Vec<Vec<Vec<Real>>> {
    text.split(']')
        .filter(|b| b.contains('('))
        .map(|b| {
            b.split(')')
                .filter(|p| p.contains('('))
                .map(|p| {
                    p.trim_start_matches(['[', '('])
                        .split(',')
                        .map(|x| x.trim().parse::<Real>().unwrap())
                        .collect()
                })
                .collect()
        })
        .collect()
}

/// Reinforcement mesh of `bars` (own nodes per bar, one law
/// `reinforcement`), as embedded_probe.cc `reinforcement`.
fn reinforcement(dim: usize, bars: &[Vec<Vec<Real>>]) -> Mesh {
    let mut nodes: Vec<&[Real]> = Vec::new();
    let mut segs = Vec::new();
    for bar in bars {
        let first = nodes.len();
        for p in bar {
            nodes.push(&p[..dim]);
        }
        for k in 0..bar.len() - 1 {
            segs.push([
                i32::try_from(first + k).unwrap(),
                i32::try_from(first + k + 1).unwrap(),
            ]);
        }
    }
    let names = vec!["reinforcement"; segs.len()];
    common::reinforcement_mesh(dim, &nodes, &segs, &names)
}

/// What the port computed for a case.
#[derive(Default)]
struct PortData {
    dim: usize,
    /// Interface elements: (end point 0, end point 1, background element).
    pieces: Vec<(Vec<Real>, Vec<Real>, i64)>,
    k: Option<Vec<Vec<Real>>>,
    u: Option<Vec<Real>>,
    f_int: Option<Vec<Real>>,
    energies: Vec<(String, Real)>,
}

fn interface_of(model: &EmbeddedInterfaceModel) -> Vec<(Vec<Real>, Vec<Real>, i64)> {
    common::interface_segments(model)
        .into_iter()
        .map(|(x0, x1, _, el)| (x0, x1, i64::try_from(el.idx()).unwrap()))
        .collect()
}

fn dense_k(model: &mut EmbeddedInterfaceModel) -> Vec<Vec<Real>> {
    model.assemble_stiffness_matrix(true).unwrap();
    let n = model.smm.displacement().unwrap().as_slice().len();
    let k = model.smm.dof_manager().matrix("K").unwrap();
    (0..n)
        .map(|i| {
            (0..n)
                .map(|j| k.get(i64::try_from(i).unwrap(), i64::try_from(j).unwrap()))
                .collect()
        })
        .collect()
}

fn energies_of(model: &mut EmbeddedInterfaceModel) -> Vec<(String, Real)> {
    let mut out = vec![("potential".to_owned(), model.energy("potential").unwrap())];
    let n = model.smm.physics.materials.laws().len();
    for m in 0..n {
        let name = model.smm.physics.materials.laws()[m].base().name.clone();
        let w = model
            .smm
            .with_material(m, LawPhase::Energy, |mat, ctx| {
                mat.energy_of(ctx, "potential")
            })
            .unwrap();
        out.push((format!("law/{name}"), w));
    }
    out
}

/// Run the case `case` of the fixture with the port (compat or default).
fn run_port(case: &str, fx: &Fixture, upstream: Option<SegmentOrder>) -> PortData {
    let p = &fx.manifest().parameters;
    let s = |k: &str| p[k].as_str().unwrap_or_default().to_owned();
    let read = |name: &str, dim| common::read_mesh(&common::data(name), dim, "mesh");
    let mut out = PortData::default();
    match case {
        "t125" => {
            let mesh = read("triangle.msh", 2);
            let rm = common::reinforcement_mesh(
                2,
                &[&[0., 0.4], &[1., 0.4]],
                &[[0, 1]],
                &["reinforcement"],
            );
            let dat = std::fs::read_to_string(common::data("embedded_element.dat")).unwrap();
            let mut model = common::model(mesh, rm, &dat);
            if let Some(order) = upstream {
                compat(&mut model, 2, order);
            }
            model
                .init_full(&EmbeddedInterfaceModelOptions::new(AnalysisMethod::Static))
                .unwrap();
            out.pieces = interface_of(&model);
            out.k = Some(dense_k(&mut model));
        }
        "t126" | "oblique" => {
            let mesh = read("embedded_mesh.msh", 2);
            let pts: [[Real; 2]; 2] = if case == "t126" {
                [[0., 0.5], [1., 0.5]]
            } else {
                [[0.07, 0.13], [0.91, 0.83]]
            };
            let rm =
                common::reinforcement_mesh(2, &[&pts[0], &pts[1]], &[[0, 1]], &["reinforcement"]);
            let dat = std::fs::read_to_string(common::data("material.dat")).unwrap();
            let mut model = common::model(mesh, rm, &dat);
            if let Some(order) = upstream {
                compat(&mut model, 2, order);
            }
            model
                .init_full(&EmbeddedInterfaceModelOptions::new(AnalysisMethod::Static))
                .unwrap();
            out.pieces = interface_of(&model);
            let nodes = common::nodes(&model);
            {
                let mut f = model.smm.external_force_mut().unwrap();
                f.as_mut_slice()[4] = -250.;
                f.as_mut_slice()[10] = -500.;
                f.as_mut_slice()[16] = -250.;
            }
            {
                let mut b = model.smm.blocked_dofs_mut().unwrap();
                for (i, x) in nodes.iter().enumerate() {
                    if common::are_float_equal(x[0], 0., 1e-7) {
                        b.as_mut_slice()[2 * i] = true;
                    }
                    if common::are_float_equal(x[1], 0., 1e-7) {
                        b.as_mut_slice()[2 * i + 1] = true;
                    }
                }
            }
            model.solve_step(None).unwrap();
            out.k = Some(dense_k(&mut model));
            out.u = Some(model.smm.displacement().unwrap().as_slice().to_vec());
            model.assemble_internal_forces().unwrap();
            out.f_int = Some(model.smm.internal_force().unwrap().as_slice().to_vec());
            out.energies = energies_of(&mut model);
        }
        "t127" => {
            let mesh = read("embedded_mesh_prestress.msh", 2);
            let rm = common::read_mesh(
                &common::data("embedded_mesh_prestress_reinforcement.msh"),
                2,
                "reinforcement_mesh",
            );
            let dat = std::fs::read_to_string(common::data("prestress.dat")).unwrap();
            let mut model = common::model(mesh, rm, &dat);
            if let Some(order) = upstream {
                compat(&mut model, 2, order);
            }
            model
                .init_full(&EmbeddedInterfaceModelOptions::new(AnalysisMethod::Static))
                .unwrap();
            out.pieces = interface_of(&model);
            for (axis, group) in [
                (SpatialDirection::X, "XBlocked"),
                (SpatialDirection::Y, "YBlocked"),
            ] {
                model
                    .smm
                    .apply_dirichlet_bc(&FixedValue { value: 0., axis }, group)
                    .unwrap();
            }
            model.solve_step(None).unwrap();
            out.u = Some(model.smm.displacement().unwrap().as_slice().to_vec());
            model.assemble_internal_forces().unwrap();
            out.f_int = Some(model.smm.internal_force().unwrap().as_slice().to_vec());
            out.energies = energies_of(&mut model);
        }
        _ => {
            // generated cases: a prescribed field, no solve
            let (mesh, dim) = if case.ends_with("_3d")
                || case.starts_with("grazing_3d")
                || case.starts_with("prestress_3d")
            {
                (common::grid_tetrahedra(3, 1.0, "concrete"), 3)
            } else if case.starts_with("triangle6") {
                (grid_triangles6(2), 2)
            } else {
                (common::grid_triangles(4, 4, 1.0, 1.0, "concrete"), 2)
            };
            let bars = parse_bars(&s("bars"));
            let mut model = common::model(mesh, reinforcement(dim, &bars), &s("material_dat"));
            if let Some(order) = upstream {
                compat(&mut model, dim, order);
            }
            model
                .init_full(&EmbeddedInterfaceModelOptions::new(AnalysisMethod::Static))
                .unwrap();
            out.pieces = interface_of(&model);
            let seed = p["field_seed"].as_u64().unwrap();
            if seed != 0 {
                random_field(&mut model, seed);
            }
            model.assemble_internal_forces().unwrap();
            out.f_int = Some(model.smm.internal_force().unwrap().as_slice().to_vec());
            out.energies = energies_of(&mut model);
            out.k = Some(dense_k(&mut model));
        }
    }
    out.dim = match case {
        c if c.ends_with("_3d") || c.starts_with("grazing_3d") || c.starts_with("prestress_3d") => {
            3
        }
        _ => 2,
    };
    out
}

/// Bit pattern key of an interface piece: (background element, end points
/// in exact lexicographic order).
type PieceKey = (i64, Vec<u64>, Vec<u64>);

fn key(x0: &[Real], x1: &[Real], bg: i64) -> PieceKey {
    let a: Vec<u64> = x0.iter().map(|v| v.to_bits()).collect();
    let b: Vec<u64> = x1.iter().map(|v| v.to_bits()).collect();
    let (lo, hi) = if x0
        .iter()
        .zip(x1)
        .map(|(p, q)| p.total_cmp(q))
        .find(|o| o.is_ne())
        == Some(std::cmp::Ordering::Greater)
    {
        (b, a)
    } else {
        (a, b)
    };
    (bg, lo, hi)
}

/// Barycentric coordinates of `p` in the simplex of `(ty, e)` of the
/// background mesh (corner nodes).
fn barycentric_in(mesh: &Mesh, ty: ElementType, e: i64, p: &[Real]) -> Vec<Real> {
    let x = common::element_coords(mesh, ty, usize::try_from(e).unwrap());
    let dim = p.len();
    common::barycentric(&x[..=dim], p)
}

/// The oracle's interface pieces `(x0, x1, background element)`.
fn oracle_pieces(dt: &DiffTest, dim: usize) -> Vec<(Vec<Real>, Vec<Real>, i64)> {
    let nodes = dt.reference_f64("interface/nodes").unwrap().data;
    let conn = dt.reference_i64("interface/connectivity").unwrap().data;
    let bg = dt
        .reference_i64("interface/background_element")
        .unwrap()
        .data;
    let node = |n: i64| {
        let n = usize::try_from(n).unwrap();
        nodes[n * dim..(n + 1) * dim].to_vec()
    };
    (0..bg.len())
        .map(|e| (node(conn[2 * e]), node(conn[2 * e + 1]), bg[e]))
        .collect()
}

/// End points of a piece as a bit-pattern key (exact lexicographic order).
fn ends(x0: &[Real], x1: &[Real]) -> (Vec<u64>, Vec<u64>) {
    let k = key(x0, x1, 0);
    (k.1, k.2)
}

/// Compare one case. `upstream`: compat mode (else the default). Returns
/// whether the port matched the oracle in place (same pieces, same order).
fn replay(case: &str, upstream: bool) -> bool {
    let test = format!(
        "embedded_{case}_{}",
        if upstream { "compat" } else { "default" }
    );
    let mut dt = DiffTest::new(&test, &format!("model/embedded/{case}"))
        .unwrap_or_else(|e| panic!("fixture model/embedded/{case}: {e}"));
    let dim = if case.contains("_3d") { 3 } else { 2 };
    let oracle = oracle_pieces(&dt, dim);
    let okeys: Vec<_> = oracle.iter().map(|(a, b, _)| ends(a, b)).collect();
    let mut osorted = okeys.clone();
    osorted.sort();
    // upstream's segment set first; the exact deduplication when the LGPL
    // order does not reproduce upstream's set (UD-408)
    let orders: &[Option<SegmentOrder>] = if upstream {
        &[
            Some(SegmentOrder::Upstream),
            Some(SegmentOrder::Lexicographic),
        ]
    } else {
        &[None]
    };
    let mut chosen = None;
    for order in orders {
        let port = run_port(case, dt.fixture(), *order);
        let mut ps: Vec<_> = port.pieces.iter().map(|(a, b, _)| ends(a, b)).collect();
        ps.sort();
        if ps == osorted {
            chosen = Some((port, *order));
            break;
        }
    }
    let Some((port, order)) = chosen else {
        panic!(
            "{test}: no order reproduces the oracle's interface pieces ({})",
            oracle.len()
        );
    };
    // the background element of every piece: the oracle's, or another
    // element containing the piece (a bar on an edge shared by both, where
    // the contributions are equal in exact arithmetic)
    let bg_mesh = background_mesh(case);
    let ty = if dim == 3 {
        ElementType::Tetrahedron4
    } else if case.starts_with("triangle6") {
        ElementType::Triangle6
    } else {
        ElementType::Triangle3
    };
    let index: HashMap<_, usize> = port
        .pieces
        .iter()
        .enumerate()
        .map(|(i, (a, b, _))| (ends(a, b), i))
        .collect();
    let mut inodes = Vec::new();
    let mut ibg = Vec::new();
    let mut survivors_differ = 0;
    let mut same_order = true;
    for (e, k) in okeys.iter().enumerate() {
        let i = index[k];
        same_order &= i == e;
        let (a, b, el) = &port.pieces[i];
        let (oa, _, oel) = &oracle[e];
        let (a, b) = if a
            .iter()
            .map(|v| v.to_bits())
            .eq(oa.iter().map(|v| v.to_bits()))
        {
            (a, b)
        } else {
            (b, a)
        };
        if el != oel {
            let mid: Vec<Real> = a.iter().zip(b).map(|(x, y)| 0.5 * (x + y)).collect();
            for elem in [*el, *oel] {
                let lam = barycentric_in(&bg_mesh, ty, elem, &mid);
                let min = lam.iter().copied().fold(Real::INFINITY, Real::min);
                assert!(
                    min >= -1e-12,
                    "{test}: piece {e} in element {el} (port) / {oel} (oracle), not in {elem}"
                );
            }
            survivors_differ += 1;
            same_order = false;
        }
        inodes.extend_from_slice(a);
        inodes.extend_from_slice(b);
        ibg.push(*oel);
    }
    dt.check_f64("interface/nodes", &inodes);
    dt.check_i64("interface/background_element", &ibg);
    if let Some(k) = &port.k {
        let rows = dt.reference_i64("K/rows").unwrap().data;
        let cols = dt.reference_i64("K/cols").unwrap().data;
        let mut values = Vec::with_capacity(rows.len());
        let mut pattern: BTreeMap<(usize, usize), ()> = BTreeMap::new();
        for (&r, &c) in rows.iter().zip(&cols) {
            let (r, c) = (usize::try_from(r).unwrap(), usize::try_from(c).unwrap());
            values.push(k[r][c]);
            pattern.insert((r, c), ());
        }
        dt.check_f64("K/values", &values);
        for (r, row) in k.iter().enumerate() {
            for (c, &v) in row.iter().enumerate() {
                assert!(
                    v == 0.0 || pattern.contains_key(&(r, c)),
                    "{test}: K({r}, {c}) = {v} is zero in the oracle"
                );
            }
        }
    }
    if let Some(u) = &port.u {
        dt.check_f64("u", u);
    }
    if let Some(f) = &port.f_int {
        dt.check_f64("f_int", f);
    }
    for (name, w) in &port.energies {
        dt.check_f64(&format!("energy/{name}"), &[*w]);
    }
    // measured differences (evidence of the rule `emb_order`)
    let rel_max = |name: &str, a: &[Real]| -> Real {
        let e = dt.reference_f64(name).unwrap().data;
        let scale = e.iter().fold(0.0_f64, |m, x| m.max(x.abs()));
        a.iter()
            .zip(&e)
            .fold(0.0_f64, |m, (x, y)| m.max((x - y).abs()))
            / if scale > 0.0 { scale } else { 1.0 }
    };
    let mut measured = Vec::new();
    if let (Some(k), Ok(rows)) = (&port.k, dt.reference_i64("K/rows")) {
        let cols = dt.reference_i64("K/cols").unwrap().data;
        let values: Vec<Real> = rows
            .data
            .iter()
            .zip(&cols)
            .map(|(&r, &c)| k[usize::try_from(r).unwrap()][usize::try_from(c).unwrap()])
            .collect();
        measured.push(format!("K {:.2e}", rel_max("K/values", &values)));
    }
    if let Some(u) = &port.u {
        measured.push(format!("u {:.2e}", rel_max("u", u)));
    }
    if let Some(f) = &port.f_int {
        measured.push(format!("f_int {:.2e}", rel_max("f_int", f)));
    }
    eprintln!(
        "{test}: {} interface elements, order {order:?}, in place: {same_order}, \
         duplicate survivors differing: {survivors_differ}; max |diff| / max |ref|: {}",
        oracle.len(),
        measured.join(", ")
    );
    dt.assert_pass();
    same_order
}

/// Upstream threw (fixture `expect.status = error`): the port's compat path
/// (the same flat tetrahedron triangles, UD-407) must refuse the case with
/// the same kind of error. The default construction handles these bars
/// (`review_v82_independent::v82_3d_adversarial_bars_random_field`,
/// `segment_tiling::em03_adversarial_bars_tile_exactly_3d`).
fn replay_expected_error(case: &str) {
    let mut dt = DiffTest::new(
        &format!("embedded_{case}_compat"),
        &format!("model/embedded/{case}"),
    )
    .unwrap();
    assert!(
        dt.expects_error(),
        "{case}: the fixture should record upstream's error"
    );
    let p = dt.fixture().manifest().parameters.clone();
    let bars = parse_bars(p["bars"].as_str().unwrap());
    let mut model = common::model(
        common::grid_tetrahedra(3, 1.0, "concrete"),
        reinforcement(3, &bars),
        p["material_dat"].as_str().unwrap(),
    );
    compat(&mut model, 3, SegmentOrder::Upstream);
    let result = model.init_full(&EmbeddedInterfaceModelOptions::new(AnalysisMethod::Static));
    let message = match result {
        Err(e) => e.to_string(),
        Ok(()) => panic!("{case}: upstream threw, the port's compat path did not"),
    };
    let kind = if message.contains("CGAL_error()") {
        "cgal_error"
    } else {
        "error"
    };
    eprintln!(
        "{case}: upstream {:?}; port: {message}",
        p["upstream_exception"]
    );
    dt.observe_error(kind, &message);
    dt.assert_pass();
}

/// The background mesh of a case (as built by `run_port`).
fn background_mesh(case: &str) -> Mesh {
    let read = |name: &str| common::read_mesh(&common::data(name), 2, "mesh");
    match case {
        "t125" => read("triangle.msh"),
        "t126" | "oblique" => read("embedded_mesh.msh"),
        "t127" => read("embedded_mesh_prestress.msh"),
        c if c.contains("_3d") => common::grid_tetrahedra(3, 1.0, "concrete"),
        c if c.starts_with("triangle6") => grid_triangles6(2),
        _ => common::grid_triangles(4, 4, 1.0, 1.0, "concrete"),
    }
}

fn replay_compat(case: &str) {
    let in_place = replay(case, true);
    assert_eq!(
        in_place,
        !ORDER_DIFFERS.contains(&case),
        "{case}: in-place match vs ORDER_DIFFERS"
    );
}

/// 3-D (UD-407): what upstream computes for the grazing bars is **no
/// interface element at all** (the flat triangles at z = 0 never meet a bar
/// at z ≈ 1/3): zero stiffness and residual of the reinforcement. The port's
/// compat path (the same flat triangles over the LGPL `LinearScan`) yields
/// at most near-degenerate pieces from degenerate flat triangles (three
/// collinear projected nodes violate CGAL's preconditions; CGAL's AABB tree
/// never tests them for this bar: its bounding boxes lie at z = 0); the
/// default construction tiles the bar exactly (other tests).
fn replay_ud407_vanishing(case: &str) {
    let dt = DiffTest::new(
        &format!("embedded_{case}_ud407"),
        &format!("model/embedded/{case}"),
    )
    .unwrap();
    assert!(
        dt.reference_i64("interface/background_element")
            .unwrap()
            .data
            .is_empty()
    );
    assert!(dt.reference_f64("K/values").unwrap().data.is_empty());
    assert!(
        dt.reference_f64("f_int")
            .unwrap()
            .data
            .iter()
            .all(|&x| x == 0.0)
    );
    let port = run_port(case, dt.fixture(), Some(SegmentOrder::Upstream));
    for (a, b, el) in &port.pieces {
        let len: Real = a
            .iter()
            .zip(b)
            .map(|(x, y)| (x - y) * (x - y))
            .sum::<Real>()
            .sqrt();
        assert!(
            len <= 1e-15,
            "{case}: compat piece of length {len} in element {el}"
        );
    }
    eprintln!(
        "{case}: oracle 0 interface elements; port compat {} near-degenerate artefact(s)",
        port.pieces.len()
    );
}

