/// 3-D (UD-407, UD-408): what upstream computes for a bar lying in the
/// boundary face z = 0 — every tetrahedron's flat triangle `(x, y, 0)` is
/// coplanar with it, so the pieces of all tetrahedra whose projected first
/// three nodes cover the bar are collected; upstream's `std::set` with the
/// invalid comparator keeps an exact duplicate (survivors depend on the CGAL
/// tree's order, which the LGPL `LinearScan` cannot reproduce) and attributes
/// pieces to tetrahedra of upper layers: 7 pieces, length +35.5 %. The port's
/// default tiles the bar exactly (length = the bar's).
#[test]
fn face_z0_3d_ud407_overcount() {
    let dt = DiffTest::new("embedded_face_z0_3d_ud407", "model/embedded/face_z0_3d").unwrap();
    let len = |a: &[Real], b: &[Real]| {
        a.iter()
            .zip(b)
            .map(|(x, y)| (x - y) * (x - y))
            .sum::<Real>()
            .sqrt()
    };
    let bar = len(&[0.07, 0.11, 0.0], &[0.89, 0.71, 0.0]);
    let oracle = oracle_pieces(&dt, 3);
    let total: Real = oracle.iter().map(|(a, b, _)| len(a, b)).sum();
    assert_eq!(oracle.len(), 7);
    assert!(
        (total / bar - 1.3554).abs() < 1e-3,
        "oracle length {total} vs bar {bar}"
    );
    let mut ends_only: Vec<_> = oracle.iter().map(|(a, b, _)| ends(a, b)).collect();
    ends_only.sort();
    ends_only.dedup();
    assert_eq!(
        ends_only.len(),
        6,
        "one exact duplicate in two elements upstream"
    );
    // pieces of a bar at z = 0 attributed to tetrahedra above the first layer
    assert!(oracle.iter().any(|(_, _, e)| *e >= 54));
    let port = run_port("face_z0_3d", dt.fixture(), None);
    let ported: Real = port.pieces.iter().map(|(a, b, _)| len(a, b)).sum();
    assert!(
        (ported - bar).abs() <= 1e-12 * bar,
        "default length {ported} vs {bar}"
    );
    eprintln!(
        "face_z0_3d: oracle {} pieces, length {total:.6} (bar {bar:.6}); port default {} pieces, exact",
        oracle.len(),
        port.pieces.len()
    );
}

