/// UD-601: CGAL's `intersection(Segment_3, Triangle_3)` in
/// `Simple_cartesian<double>` (the kernel of upstream's intersector) of the
/// grazing bars with the four faces of every tetrahedron, against the port's
/// LGPL `triangle_segment_intersection` on the same inputs: kinds and
/// coordinates bitwise. If they agree, the hits the face construction misses
/// at δ = 1e-10 are CGAL's own (inexact predicates), not a defect of the port.
#[test]
fn faces_grazing_3d_cgal_intersections() {
    use akantu_geometry::intersections::{
        TriangleSegmentIntersection, triangle_segment_intersection,
    };
    use akantu_geometry::kernel::{Point3, Segment3, Triangle3};
    let mut dt = DiffTest::new(
        "embedded_faces_grazing_3d",
        "model/embedded/faces_grazing_3d",
    )
    .expect("fixture model/embedded/faces_grazing_3d");
    let queries = dt.reference_f64("queries").unwrap().data;
    let mesh = common::grid_tetrahedra(3, 1.0, "concrete");
    let conn = mesh
        .connectivity(ElementType::Tetrahedron4, GhostType::NotGhost)
        .unwrap();
    let nodes_g = mesh.nodes();
    let pt = |n: i32| {
        let x = nodes_g.get_tuple(usize::try_from(n).unwrap()).unwrap();
        Point3::new(x[0], x[1], x[2])
    };
    let (mut kind, mut coords) = (Vec::new(), Vec::new());
    for q in queries.as_chunks::<6>().0 {
        let seg = Segment3::new(Point3::new(q[0], q[1], q[2]), Point3::new(q[3], q[4], q[5]));
        for c in conn.tuples() {
            let (a, b, cc, d) = (pt(c[0]), pt(c[1]), pt(c[2]), pt(c[3]));
            for tri in [
                Triangle3::new(a, b, cc),
                Triangle3::new(b, cc, d),
                Triangle3::new(cc, d, a),
                Triangle3::new(d, a, b),
            ] {
                let (k, v) = match triangle_segment_intersection(&tri, &seg).unwrap() {
                    None => (0, [0.0; 6]),
                    Some(TriangleSegmentIntersection::Point(p)) => (1, [p.x, p.y, p.z, 0., 0., 0.]),
                    Some(TriangleSegmentIntersection::Segment(s)) => (
                        2,
                        [
                            s.source.x, s.source.y, s.source.z, s.target.x, s.target.y, s.target.z,
                        ],
                    ),
                };
                kind.push(k);
                coords.extend_from_slice(&v);
            }
        }
    }
    dt.check_i64("kind", &kind);
    dt.check_f64("coords", &coords);
    dt.assert_pass();
}
